const uptrace = require('@uptrace/node');

uptrace.configureOpentelemetry({
  dsn: process.env.UPTRACE_DSN,
  serviceName: 'express-service',
  serviceVersion: '1.0.0',
});

const express = require('express');
const app = express();

app.get('/api/users', (req, res) => {
  res.json({ users: [{ id: 1, name: 'Alice' }, { id: 2, name: 'Bob' }] });
});

app.listen(3000, () => console.log('Express running on http://localhost:3000'));

using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

var builder = WebApplication.CreateBuilder(args);

var dsn = Environment.GetEnvironmentVariable("UPTRACE_DSN") ?? "https://<token>@uptrace.dev/<project_id>";

builder.Services.AddOpenTelemetry()
    .ConfigureResource(resource => resource.AddService("dotnet-api-service"))
    .WithTracing(tracing => tracing
        .AddAspNetCoreInstrumentation()
        .AddHttpClientInstrumentation()
        .AddOtlpExporter(opt => {
            opt.Endpoint = new Uri("https://otlp.uptrace.dev:4317");
            opt.Headers = $"uptrace-dsn={dsn}";
            opt.Protocol = OpenTelemetry.Exporter.OtlpExportProtocol.Grpc;
        }));

var app = builder.Build();
app.MapGet("/ping", () => "pong");
app.Run();

[dependencies]
opentelemetry = { version = "0.24", features = ["trace"] }
opentelemetry-otlp = { version = "0.17", features = ["grpc-tonic"] }
tracing = "0.1"
tracing-subscriber = "0.3"
tracing-opentelemetry = "0.25"
tokio = { version = "1", features = ["full"] }

use opentelemetry_otlp::WithExportConfig;
use tracing_subscriber::layer::SubscriberExt;
use tracing_subscriber::util::SubscriberInitExt;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let dsn = std::env::var("UPTRACE_DSN").expect("UPTRACE_DSN must be set");

    let tracer = opentelemetry_otlp::new_pipeline()
        .tracing()
        .with_exporter(
            opentelemetry_otlp::new_exporter()
                .tonic()
                .with_endpoint("https://otlp.uptrace.dev:4317")
                .with_metadata(tonic::metadata::MetadataMap::from_headers((
                    "uptrace-dsn".parse().unwrap(),
                    dsn.parse().unwrap(),
                ))),
        )
        .install_batch(opentelemetry_sdk::runtime::Tokio)?;

    tracing_subscriber::registry()
        .with(tracing_opentelemetry::layer().with_tracer(tracer))
        .init();

    tracing::info!("Rust service initialized with Uptrace.");
    Ok(())
}

CREATE USER 'otel_monitor'@'%' IDENTIFIED BY 'secret_password';
GRANT PROCESS, REPLICATION CLIENT, SELECT ON *.* TO 'otel_monitor'@'%';
FLUSH PRIVILEGES;

server {
    listen 127.0.0.1:80;
    server_name localhost;

    location /nginx_status {
        stub_status on;
        access_log off;
        allow 127.0.0.1;
        deny all;
    }
}
